local function ensureDir(path)
  if path == "" then
    return true
  end
  if fs.exists(path) then
    return true
  end
  local parent = path:match("^(.*)/[^/]+$")
  if parent and parent ~= "" and parent ~= path then
    ensureDir(parent)
  end
  local ok = pcall(fs.makeDir, path)
  return ok or fs.exists(path)
end

local function readFile(path)
  if not fs.exists(path) then
    return nil
  end
  local handle = fs.open(path, "r")
  if not handle then
    return nil
  end
  local data = handle.readAll()
  handle.close()
  return data
end

local function writeFile(path, data)
  ensureDir(path:match("^(.*)/[^/]+$") or "")
  local handle = fs.open(path, "w")
  if not handle then
    return false
  end
  handle.write(data)
  handle.close()
  return true
end

local function download(url)
  if not http then
    return nil
  end
  local ok, response = pcall(http.get, url)
  if not ok or not response then
    return nil
  end
  local data = response.readAll()
  response.close()
  if not data or #data < 10000 then
    return nil
  end
  return data
end

local function ensureBasalt()
  local existing = readFile("/basalt-ha.lua") or ""
  if existing:find("1.7.0", 1, true) then
    print("Basalt 1.7.0 already installed (/basalt-ha.lua)")
    return true
  end
  for _, url in ipairs(BASALT_URLS) do
    print("Downloading Basalt 1.7.0: " .. url)
    local data = download(url)
    if data and data:find("1.7.0", 1, true) then
      if not writeFile("/basalt-ha.lua", data) then
        print("Could not write /basalt-ha.lua")
        return false
      end
      print("Basalt installed.")
      return true
    elseif data then
      print("Downloaded file is not Basalt 1.7.0; ignoring it.")
    end
  end
  local fallback = readFile("/basalt.lua") or ""
  if fallback:find("1.7.0", 1, true) then
    print("Download failed; copying the compatible /basalt.lua.")
    return writeFile("/basalt-ha.lua", fallback)
  end
  print("Could not download Basalt 1.7.0.")
  print("Check that HTTP is enabled, or install it manually:")
  print(BASALT_URLS[1])
  print("Save it as /basalt-ha.lua and run this installer again.")
  return false
end

print("Home Assistant installer (" .. TARGET .. ")")
for path, content in pairs(files) do
  local existing = readFile(path)
  if existing == content then
    print("unchanged " .. path)
  elseif writeFile(path, content) then
    print("installed " .. path)
  else
    print("FAILED " .. path)
    return
  end
end

if not ensureBasalt() then
  return
end

-- Basalt 1.7.0's minified Slider has two bugs: draw uses a position local
-- that the minifier dropped, and click/drag compares absolute mouse
-- coordinates against relative positions. Fix both in our private copy.
local function patchBasalt()
  local path = "/basalt-ha.lua"
  local data = readFile(path)
  if not data then return end
  local changed = false

  local drawNeedle = 'addDraw("slider",function()local a_a,b_a=__a:getSize()'
  local drawFix = "local obx,oby=__a:getPosition()"
  if not data:find(drawFix, 1, true) then
    local start = data:find(drawNeedle, 1, true)
    if start then
      data = data:sub(1, start - 1) .. drawNeedle .. drawFix .. data:sub(start + #drawNeedle)
      changed = true
    else
      print("WARNING: could not apply the Basalt slider draw patch.")
    end
  end

  local mouseNeedle = 'local function cd(__a,a_a,b_a,c_a)local d_a,_aa=__a:getPosition()local aaa,baa=__a:getSize()'
  local mouseFix = 'local function cd(__a,a_a,b_a,c_a)local d_a,_aa=__a:getAbsolutePosition()local aaa,baa=__a:getSize()'
  if not data:find(mouseFix, 1, true) then
    local start = data:find(mouseNeedle, 1, true)
    if start then
      data = data:sub(1, start - 1) .. mouseFix .. data:sub(start + #mouseNeedle)
      changed = true
    else
      print("WARNING: could not apply the Basalt slider mouse patch.")
    end
  end

  if changed and writeFile(path, data) then
    print("Applied Basalt 1.7.0 slider fixes.")
  end
end

patchBasalt()
-- Shared startup configuration for generated installers.
-- This file is embedded into every generated installer. Edit it here, then run
-- `make build`; do not duplicate these choices in individual installers.

local STARTUP_MARKER_START = "-- >>> computercraft-home-assistant >>>"
local STARTUP_MARKER_END = "-- <<< computercraft-home-assistant <<<"

local STARTUP_CHOICES = {
  { id = "1", command = "ha", label = "Home Assistant client", path = "/ha.lua" },
  { id = "2", command = "switch", label = "Switch device", path = "/switch.lua" },
  { id = "3", command = "dimmer", label = "Dimmer device", path = "/dimmer.lua" },
}

local function startupRemoveBlock(text)
  local start = text:find(STARTUP_MARKER_START, 1, true)
  if not start then
    return text
  end
  local finish = text:find(STARTUP_MARKER_END, start, true)
  if not finish then
    return text:sub(1, start - 1)
  end
  finish = finish + #STARTUP_MARKER_END
  if text:sub(finish, finish) == "\n" then
    finish = finish + 1
  end
  return text:sub(1, start - 1) .. text:sub(finish)
end

local function startupWrite(command)
  local existing = readFile("/startup.lua") or ""
  existing = startupRemoveBlock(existing)
  local block = STARTUP_MARKER_START
    .. "\n"
    .. string.format("shell.run(%q)\n", command)
    .. STARTUP_MARKER_END
    .. "\n"
  if existing ~= "" then
    block = block .. "\n" .. existing
  end
  return writeFile("/startup.lua", block)
end

local function startupLabel()
  local current = os.getComputerLabel() or ""
  print("")
  if current ~= "" then
    print("Computer label [" .. current .. "]:")
  else
    print("Computer label (blank leaves it unchanged):")
  end
  local ok, input = pcall(read)
  if not ok or input == nil then
    return
  end
  input = tostring(input):match("^%s*(.-)%s*$")
  if input == "" then
    print("Computer label unchanged.")
    return
  end
  local setOk, err = pcall(os.setComputerLabel, input)
  if setOk then
    print("Computer label set to " .. input .. ".")
  else
    print("Could not set computer label: " .. tostring(err))
  end
end

local function startupConfigure()
  local available = {}
  local byId = {}
  for _, choice in ipairs(STARTUP_CHOICES) do
    if files[choice.path] then
      available[#available + 1] = choice
      byId[choice.id] = choice
    end
  end
  if #available == 0 then
    return
  end

  print("")
  print("Startup program:")
  for _, choice in ipairs(available) do
    print("  " .. choice.id .. ") " .. choice.label .. " (" .. choice.command .. ")")
  end
  print("  0) Do not change /startup.lua")

  while true do
    print("Select a startup program [0]:")
    local ok, input = pcall(read)
    if not ok or input == nil then
      print("Startup unchanged (no input).")
      return
    end
    input = tostring(input):match("^%s*(.-)%s*$")
    if input == "" then
      input = "0"
    end
    if input == "0" then
      print("Startup unchanged.")
      return
    end
    local choice = byId[input]
    if choice then
      if startupWrite(choice.command) then
        print(string.format("Updated /startup.lua: shell.run(%q)", choice.command))
      else
        print("Could not update /startup.lua.")
      end
      return
    end
    print("Invalid selection.")
  end
end

startupLabel()
startupConfigure()

print("")
print("Done. Run: " .. RUN_COMMAND)
